import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 1000007;
    static boolean[] visitedNodes = new boolean[MAX_SIZE];
    static final long MOD_CONST = 1000000007L;
    static long[] divisorCounts = new long[MAX_SIZE];
    static long[] cycleLengths = new long[MAX_SIZE];
    static long[] dpArray = new long[MAX_SIZE];

    public static int getInput(Scanner sc) {
        return sc.nextInt();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long answer = 1;
        int totalP = getInput(sc);
        int totalK = getInput(sc);

        for (int i = 0; i < totalP; i++) {
            if (!visitedNodes[i]) {
                int length = 0;
                long current = i;
                while (!visitedNodes[(int) current]) {
                    visitedNodes[(int) current] = true;
                    current = (totalK * current) % totalP;
                    length++;
                }
                cycleLengths[length]++;
            }
        }

        for (int i = 1; i <= totalP; i++) {
            dpArray[i] = (cycleLengths[i] * i) % MOD_CONST;
        }

        for (int i = 1; i <= totalP; i++) {
            divisorCounts[i] = (divisorCounts[i] + dpArray[i]) % MOD_CONST;
            for (int j = i + i; j <= totalP; j += i) {
                divisorCounts[j] = (dpArray[i] + divisorCounts[j]) % MOD_CONST;
            }
        }

        for (int i = 1; i <= totalP; i++) {
            if (i == 1) {
                for (int j = 0; j < cycleLengths[i] - 1; j++) {
                    answer = (answer * cycleLengths[i]) % MOD_CONST;
                }
            } else {
                for (int j = 0; j < cycleLengths[i]; j++) {
                    answer = (answer * divisorCounts[i]) % MOD_CONST;
                }
            }
        }

        if (totalK == 1) {
            answer = (answer * divisorCounts[1]) % MOD_CONST;
        }

        System.out.println(answer);
        sc.close();
    }
}
